#include "PluginEditor.h"
#include "Export/Midi.h"
WeeEditor::WeeEditor(WeeProcessor& proc):AudioProcessorEditor(proc),p(proc){
 look.setColour(juce::TextButton::buttonColourId,juce::Colour(0xff1caee5));look.setColour(juce::TextButton::textColourOffId,juce::Colours::white);setLookAndFeel(&look);
 for(auto* c:std::initializer_list<juce::Component*>{&style,&key,&scale,&bars,&bpm,&volume,&sync,&generate,&play,&save,&drag,&undo,&redo})addAndMakeVisible(c);
 style.addItemList({"Pop","Dark Pop","Indie Pop"},1);key.addItemList({"C","C#","D","D#","E","F","F#","G","G#","A","A#","B"},1);scale.addItemList({"Minor","Major"},1);bars.addItemList({"8 bars","16 bars"},1);
 aStyle=std::make_unique<CA>(p.params,"style",style);aKey=std::make_unique<CA>(p.params,"key",key);aScale=std::make_unique<CA>(p.params,"scale",scale);aBars=std::make_unique<CA>(p.params,"bars",bars);
 for(auto*s:{&bpm,&volume}){s->setSliderStyle(juce::Slider::LinearHorizontal);s->setTextBoxStyle(juce::Slider::TextBoxRight,false,65,25);}
 aBpm=std::make_unique<SA>(p.params,"bpm",bpm);aVolume=std::make_unique<SA>(p.params,"gain",volume);aSync=std::make_unique<juce::AudioProcessorValueTreeState::ButtonAttachment>(p.params,"sync",sync);
 generate.onClick=[this]{past.push_back(p.snapshot());if(past.size()>32)past.erase(past.begin());future.clear();p.generate();repaint();};
 undo.onClick=[this]{if(past.empty())return;future.push_back(p.snapshot());p.replace(past.back());past.pop_back();};redo.onClick=[this]{if(future.empty())return;past.push_back(p.snapshot());p.replace(future.back());future.pop_back();};
 play.onClick=[this]{p.preview=!p.preview.load();};save.onClick=[this]{exportMidi(false);};drag.onClick=[this]{exportMidi(true);};
 setResizable(true,true);setResizeLimits(700,500,1400,1000);setSize(900,620);startTimerHz(20);
}
void WeeEditor::exportMidi(bool dragging){auto c=p.snapshot();c.settings.bpm=p.tempo.load();if(dragging){auto f=juce::File::getSpecialLocation(juce::File::tempDirectory).getNonexistentChildFile("WEE-", ".mid");if(wee::saveMidi(c,f.getFullPathName().toStdString()))juce::DragAndDropContainer::performExternalDragDropOfFiles({f.getFullPathName()},false,this);return;}
 chooser=std::make_unique<juce::FileChooser>("Save generated MIDI",juce::File::getSpecialLocation(juce::File::userDocumentsDirectory).getChildFile("WEE.mid"),"*.mid");juce::Component::SafePointer<WeeEditor> safe(this);chooser->launchAsync(juce::FileBrowserComponent::saveMode|juce::FileBrowserComponent::canSelectFiles|juce::FileBrowserComponent::warnAboutOverwriting,[safe,c](const juce::FileChooser& fc){if(!safe)return;auto f=fc.getResult();if(f==juce::File{})return;if(!wee::saveMidi(c,f.withFileExtension("mid").getFullPathName().toStdString()))juce::AlertWindow::showMessageBoxAsync(juce::MessageBoxIconType::WarningIcon,"Export failed","Could not write MIDI file.");});}
void WeeEditor::resized(){int w=getWidth();style.setBounds(30,115,180,35);key.setBounds(225,115,90,35);scale.setBounds(330,115,120,35);bars.setBounds(465,115,110,35);sync.setBounds(w-150,115,130,35);bpm.setBounds(30,175,250,35);volume.setBounds(310,175,250,35);generate.setBounds(w-235,175,205,45);int y=getHeight()-65;int x=30;for(auto*b:{&play,&save,&drag,&undo,&redo}){b->setBounds(x,y,(w-80)/5,38);x+=(w-80)/5+5;}}
void WeeEditor::paint(juce::Graphics&g){g.fillAll(juce::Colour(0xfff1f6fa));g.setColour(juce::Colours::white);g.fillRoundedRectangle(15.f,15.f,float(getWidth()-30),75.f,24);g.setColour(juce::Colour(0xff14a9dc));g.setFont(42);g.drawText("wee",35,20,130,60,juce::Justification::centredLeft);g.setFont(16);g.setColour(juce::Colour(0xff526777));g.drawText("CREATE  /  Synthesized piano",185,30,450,30,juce::Justification::centredLeft);g.drawText("Preview BPM                         Volume",35,150,500,25,juce::Justification::centredLeft);
 auto c=p.snapshot();juce::Rectangle<float> r(30,245,float(getWidth()-60),float(getHeight()-330));g.setColour(juce::Colours::white);g.fillRoundedRectangle(r,15);g.setColour(juce::Colour(0xffdce6ed));for(int i=0;i<=c.settings.bars*4;++i){float x=r.getX()+r.getWidth()*i/(c.settings.bars*4);g.drawVerticalLine(int(x),r.getY(),r.getBottom());}for(auto&n:c.notes){float x=r.getX()+float(n.beat/(c.settings.bars*4))*r.getWidth();float y=r.getBottom()-(n.pitch-48)*r.getHeight()/48;g.setColour(juce::Colour(0xff21b4e6));g.fillRoundedRectangle(x,y,std::max(3.f,float(n.length/(c.settings.bars*4))*r.getWidth()),5,2);}g.setColour(juce::Colour(0xff526777));g.setFont(14);g.drawText(p.unsupportedMeter?"Unsupported time signature: WEE requires 4/4":("Piano  |  "+juce::String(p.tempo.load(),1)+" BPM  |  Seed "+juce::String(c.settings.seed)),30,getHeight()-92,getWidth()-60,22,juce::Justification::centredLeft);}
